<script setup lang="ts">
import {computed,defineAsyncComponent,onMounted,onUnmounted,ref} from 'vue'
import {useI18n} from 'vue-i18n'
import {api,errorMessage} from '../lib/api'
import {heatmapPalettes} from '../lib/heatmap'
import {historyRooms} from '../lib/history'
import {formatValue,time,unit} from '../lib/state'
import type {Dashboard,Floorplan,History,Metric,ChartMetric,Room} from '../lib/types'
import Plan from '../components/Plan.vue'
import Notice from '../components/Notice.vue'
import Icon from '../components/Icon.vue'
const HistoryChart=defineAsyncComponent(()=>import('../components/HistoryChart.vue'))
const {t}=useI18n()
const data=ref<Dashboard|null>(null),plan=ref<Floorplan|null>(null),loading=ref(true),error=ref(''),metric=ref<Metric>('temperature'),chartMetric=ref<ChartMetric>('temperature'),markers=ref(true),selected=ref(''),history=ref<History|null>(null),historyError=ref(''),historyBusy=ref(false),timeline=ref(100),lastRefresh=ref(0)
let timer:ReturnType<typeof setInterval>|undefined
const start=ref(Date.now()-86400000),end=ref(Date.now())
const snapshotTime=computed(()=>start.value+(end.value-start.value)*timeline.value/100)
const historicRooms=computed<Room[]>(()=>{if(timeline.value===100)return data.value?.rooms??[];return (data.value?.rooms??[]).map(room=>{const latest=new Map<string,History['points'][number]>();for(const p of history.value?.points??[]){const ts=Date.parse(p.timestamp);if(p.room_id===room.id&&ts<=snapshotTime.value&&snapshotTime.value-ts<=3600000){const old=latest.get(p.sensor_id);if(!old||Date.parse(old.timestamp)<ts)latest.set(p.sensor_id,p)}}const ps=[...latest.values()];const avg=(key:Metric)=>{const vals=ps.map(p=>p[key]).filter((v):v is number=>v!=null);return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null};return {...room,available:ps.length>0,temperature:avg('temperature'),humidity:avg('humidity')}})})
const selectedRoom=computed(()=>historicRooms.value.find(r=>r.id===selected.value))
const selectedHasHistory=computed(()=>historyRooms(data.value?.rooms??[],data.value?.sensors??[],history.value?.points??[]).some(r=>r.id===selected.value))
const roomIntervals=computed(()=>Object.fromEntries((data.value?.rooms??[]).map(room=>{const values=(data.value?.sensors??[]).filter(s=>s.room_id===room.id).map(s=>s.sample_interval_seconds);return [room.id,values.length?Math.min(...values):900]})))
const active=computed(()=>data.value?.sensors.filter(s=>s.available).length??0)
const pending=computed(()=>data.value?.sensors.filter(s=>s.enabled&&!s.available&&['waiting','reading','retrying'].includes(s.read_state??'')).length??0)
async function load(initial=false){if(initial)loading.value=true;error.value='';try{const [d,p]=await Promise.all([api<Dashboard>('/dashboard'),api<Floorplan>('/floorplan')]);data.value=d;plan.value=p;lastRefresh.value=Date.now()}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function loadHistory(){if(historyBusy.value)return;historyBusy.value=true;historyError.value='';end.value=Date.now();start.value=end.value-86400000;try{history.value=await api<History>('/history?'+new URLSearchParams({start:new Date(start.value).toISOString(),end:new Date(end.value).toISOString(),bucket:'raw'}))}catch(e){historyError.value=errorMessage(e)}finally{historyBusy.value=false}}
function showRoom(id:string){selected.value=id;chartMetric.value=metric.value;if(!history.value)void loadHistory()}
function visibility(){if(!document.hidden&&Date.now()-lastRefresh.value>30000)void load()}
onMounted(()=>{void load(true);timer=setInterval(()=>{if(!document.hidden)void load()},30000);document.addEventListener('visibilitychange',visibility)})
onUnmounted(()=>{clearInterval(timer);document.removeEventListener('visibilitychange',visibility)})
</script>
<template>
<main class="page dashboard-page">
<header class="page-header"><div><div class="eyebrow">SENSOGRID / {{ t('now') }}</div><h1>{{ t('homeClimate') }}</h1><p>{{ time(data?.now) }}</p></div><div class="page-actions"><span v-if="data?.mode==='demo'" class="tag warn"><i></i>{{ t('demo') }}</span><span v-else-if="data?.mode==='off'" class="tag warn">{{ t('off') }}</span><button class="icon-button" :aria-label="t('refresh')" @click="load()"><Icon name="refresh" :size="17" /></button></div></header>
<Notice v-if="error" kind="error">{{ t('connectionLost') }} <button class="text-button" @click="load(true)">{{ t('retry') }}</button><details><summary>{{ t('details') }}</summary>{{ error }}</details></Notice>
<Notice v-if="data?.mode==='demo'">{{ t('demoNote') }}</Notice>
<div v-if="loading" class="skeleton plan" :aria-label="t('loading')"></div>
<template v-else-if="data&&plan">
<section class="dashboard-metrics"><div class="metric-block"><div class="label"><Icon name="thermo" :size="15" />{{ t('average') }} · {{ t('temperature') }}</div><div class="value">{{ formatValue(data.average_temperature,'temperature') }}<span>{{ unit('temperature') }}</span></div></div><div class="metric-block"><div class="label"><Icon name="drop" :size="15" />{{ t('average') }} · {{ t('humidity') }}</div><div class="value">{{ formatValue(data.average_humidity,'humidity',0) }}<span>%</span></div></div><div class="sensor-metric"><strong>{{ active }} <span class="muted">/ {{ data.sensors.length }}</span></strong><small>{{ t('availableSensors') }}</small><small v-if="pending">{{ t('pendingSensors',{count:pending}) }}</small></div></section>
<section>
<div class="workspace-heading"><h2>{{ plan.name||t('apartment') }}</h2><div class="segmented"><button :class="{active:metric==='temperature'}" @click="metric='temperature'"><Icon name="thermo" :size="14" />{{ t('temperature') }}</button><button :class="{active:metric==='humidity'}" @click="metric='humidity'"><Icon name="drop" :size="14" />{{ t('humidity') }}</button></div></div>
<div v-if="!plan.rooms.length" class="empty-state"><Icon name="plan" :size="38" /><h2>{{ t('noRooms') }}</h2><p>{{ t('noRoomsNote') }}</p><RouterLink to="/floorplan" class="subtle-link">{{ t('editPlan') }}<Icon name="arrow" :size="15" /></RouterLink></div>
<div v-else class="plan-workspace"><div class="plan-canvas"><Plan :plan="plan" :values="historicRooms" :metric="metric" :markers="markers" :selected="selected" @room="showRoom" /><div class="workspace-heading"><label class="check"><input v-model="markers" type="checkbox">{{ t('showMarkers') }}</label><div class="legend"><span>{{ t(metric==='temperature'?'cold':'lowHumidity') }}</span><div class="legend-scale" :style="{background:'linear-gradient(90deg, '+heatmapPalettes[metric].join(', ')+')'}" :title="t('heatmapHint')"></div><span>{{ t(metric==='temperature'?'warm':'highHumidity') }}</span></div></div></div><aside class="room-list"><div class="room-list-heading">{{ t('rooms') }} / {{ historicRooms.length }}</div><button v-for="room in historicRooms" :key="room.id" class="room-row" @click="showRoom(room.id)"><span class="room-title">{{ room.name }}<i class="status-dot" :class="{on:room.available}"></i></span><span class="room-numbers"><span>{{ formatValue(room.temperature,'temperature') }} {{ unit('temperature') }}</span><span>{{ formatValue(room.humidity,'humidity',0) }} %</span></span></button></aside></div>
<div v-if="plan.rooms.length" class="timeline"><div class="timeline-title">{{ t(timeline===100?'live':'historic') }}<div class="muted" style="font-size:10px;margin-top:5px">{{ timeline===100?t('now'):time(new Date(snapshotTime).toISOString()) }}</div></div><div class="timeline-range"><input v-model.number="timeline" type="range" min="0" max="100" step="1" :disabled="historyBusy" :aria-label="t('timeline')" @pointerdown="!history&&!historyBusy&&loadHistory()" @focus="!history&&!historyBusy&&loadHistory()"><div class="timeline-labels"><span>−24 h</span><span>−12 h</span><span>{{ t('now') }}</span></div></div><button v-if="timeline<100" @click="timeline=100">{{ t('live') }}</button></div>
<p v-if="timeline<100" class="helper">{{ t('historicNote') }}</p><Notice v-if="historyError" kind="error">{{ t('error') }} <button class="text-button" @click="loadHistory">{{ t('retry') }}</button><details><summary>{{ t('details') }}</summary>{{ historyError }}</details></Notice>
<div class="status-line"><span>{{ t('collector') }}: {{ data.status.collector }}</span><span>{{ t('storage') }}: {{ data.status.storage }}</span></div><Notice v-if="data.status.last_error" kind="error">{{ t('requestFailed') }}<details><summary>{{ t('details') }}</summary>{{ data.status.last_error }}</details></Notice>
</section>
</template>
<Teleport to="body"><div v-if="selectedRoom" class="modal-backdrop" @pointerdown.self.prevent @keydown.esc="selected=''"><section v-dialog class="modal" role="dialog" aria-modal="true" :aria-label="selectedRoom.name"><header class="modal-header"><div><div class="eyebrow">{{ t('roomDetail') }}</div><h2>{{ selectedRoom.name }}</h2></div><button class="icon-button" :aria-label="t('close')" @click="selected=''"><Icon name="close" /></button></header><div class="dashboard-metrics"><div class="metric-block"><div class="label">{{ t('temperature') }}</div><div class="value">{{ formatValue(selectedRoom.temperature,'temperature') }}<span>{{ unit('temperature') }}</span></div></div><div class="metric-block"><div class="label">{{ t('humidity') }}</div><div class="value">{{ formatValue(selectedRoom.humidity,'humidity',0) }}<span>%</span></div></div></div><p v-if="!selectedRoom.available" class="helper">{{ t('noReadings') }}</p><template v-if="selectedHasHistory||historyBusy"><div class="segmented room-chart-switch"><button v-for="kind in (['temperature','humidity','both'] as const)" :key="kind" :class="{active:chartMetric===kind}" @click="chartMetric=kind">{{ t(kind) }}</button></div><div v-if="historyBusy" class="skeleton" :aria-label="t('loading')"></div><HistoryChart v-else-if="history?.points.length" :points="history.points" :rooms="data?.rooms??[]" :selected="[selected]" :metric="chartMetric" :intervals="roomIntervals" :start="start" :end="end" /><p v-else class="helper">{{ t('noHistory') }}</p></template><div v-for="sensor in data?.sensors.filter(s=>s.room_id===selected)" :key="sensor.id" class="sensor-item"><div><h3>{{ sensor.name }}</h3><p>{{ t('lastSeen') }}: {{ time(sensor.last_seen) }}</p></div><span class="tag">{{ t(sensor.available?'online':'unavailable') }}</span></div><RouterLink v-if="selectedHasHistory" :to="{path:'/history',query:{room:selected}}" class="subtle-link" @click="selected=''">{{ t('showHistory') }}<Icon name="arrow" :size="16" /></RouterLink></section></div></Teleport>
</main>
</template>
